package app.noir.mobile;
import android.app.AlertDialog;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.time.*;
import java.util.*;

final class PhoneRewardCard {
 static final Map<DataStore,Cache> CACHE=new WeakHashMap<>();static final class Cache{long version;LocalDate day;PhoneRewards.Stats stats;}
 static synchronized PhoneRewards.Stats stats(DataStore data){long version=data.version;LocalDate today=LocalDate.now();Cache cache=CACHE.get(data);if(cache!=null&&cache.version==version&&cache.day.equals(today))return cache.stats;List<PhoneRewards.Event> events=new ArrayList<>();for(JSONObject i:DataStore.objects(data.itemsShared()))for(JSONObject v:DataStore.objects(i.optJSONArray("viewings"))){long at=DataStore.date(v.optString("watchedAt"));events.add(new PhoneRewards.Event(at>0?Instant.ofEpochMilli(at).atZone(ZoneId.systemDefault()).toLocalDate():null,at>0&&!v.optBoolean("dateUnknown")&&!v.optBoolean("approximate")));}PhoneRewards.Stats result=PhoneRewards.calculate(events,today);cache=new Cache();cache.version=version;cache.day=today;cache.stats=result;CACHE.put(data,cache);return result;}
 static int yearViewings(DataStore data){int count=0,year=LocalDate.now().getYear();for(JSONObject i:DataStore.objects(data.itemsShared()))for(JSONObject v:DataStore.objects(i.optJSONArray("viewings"))){long at=DataStore.date(v.optString("watchedAt"));if(at>0&&!v.optBoolean("dateUnknown")&&Instant.ofEpochMilli(at).atZone(ZoneId.systemDefault()).getYear()==year)count++;}return count;}
 static int goal(DataStore data){return Math.max(1,Math.min(100,data.prefs().optInt("weeklyGoal",5)));}
 static void show(MainActivity a,LinearLayout host,boolean animate){host.removeAllViews();PhoneRewards.Stats s=stats(a.data);int goal=goal(a.data);LinearLayout card=a.column();card.setPadding(a.dp(18),a.dp(18),a.dp(18),a.dp(16));card.setBackground(MainActivity.bg(Color.rgb(36,31,25),a.dp(20)));host.addView(card,new LinearLayout.LayoutParams(-1,-2));
  LinearLayout head=new LinearLayout(a);head.setGravity(Gravity.CENTER_VERTICAL);LinearLayout copy=a.column();TextView title=a.text("Your viewing life",20,MainActivity.WHITE);title.setTypeface(null,Typeface.BOLD);copy.addView(title);copy.addView(a.text(s.streak>0?Loc.f("Day %d streak",s.streak):"A little watching, a little joy.",13,MainActivity.GOLD));head.addView(copy,new LinearLayout.LayoutParams(0,-2,1));
  FrameLayout ring=new FrameLayout(a);View arc=new View(a){final Paint p=new Paint(3);@Override protected void onDraw(Canvas c){float inset=a.dp(4);RectF r=new RectF(inset,inset,getWidth()-inset,getHeight()-inset);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(a.dp(4));p.setStrokeCap(Paint.Cap.ROUND);p.setColor(0x40e4c084);c.drawOval(r,p);p.setColor(MainActivity.GOLD);c.drawArc(r,-90,360*Math.min(1,s.week/(float)goal),false,p);}};ring.addView(arc,new FrameLayout.LayoutParams(-1,-1));TextView value=a.text(s.week+"/"+goal,16,MainActivity.GOLD);value.setGravity(Gravity.CENTER);ring.addView(value,new FrameLayout.LayoutParams(-1,-1));ring.setContentDescription(Loc.f("Weekly goal: %d of %d",s.week,goal));ring.setOnClickListener(v->editGoal(a,host));Motion.card(ring);head.addView(ring,new LinearLayout.LayoutParams(a.dp(72),a.dp(72)));card.addView(head);
  LinearLayout numbers=new LinearLayout(a);String[] labels={"Viewings","This week","Day streak"};int[] values={s.total,s.week,s.streak};for(int n=0;n<3;n++){LinearLayout cell=a.column();cell.setPadding(0,a.dp(12),0,a.dp(8));TextView number=a.text(String.valueOf(values[n]),23,MainActivity.WHITE);number.setTypeface(null,Typeface.BOLD);cell.addView(number);cell.addView(a.text(labels[n],11,MainActivity.MUTED));numbers.addView(cell,new LinearLayout.LayoutParams(0,-2,1));if(animate)Motion.countUp(number,values[n]);}card.addView(numbers);
  TextView insight=a.text(insight(a.data),12,MainActivity.MUTED);card.addView(insight);card.addView(a.text(a.data.prefs().optBoolean("goalPaused")?Loc.t("Goal paused"):PhoneRewards.pacing(yearViewings(a.data),java.time.LocalDate.now()),12,MainActivity.GOLD));TextView share=a.text(Loc.t("Save a milestone card ›"),12,MainActivity.GOLD);share.setPadding(0,a.dp(12),0,0);share.setOnClickListener(v->new AlertDialog.Builder(a).setTitle(Loc.t("Your viewing life")).setItems(new String[]{Loc.t("Day streak"),Loc.t("Weekly goal"),Loc.t("Milestones")},(d,n)->{String label=n==0?Loc.t("Day streak"):n==1?Loc.t("Weekly goal"):Loc.t("Milestones");String cardValue=n==0?String.valueOf(s.streak):n==1?s.week+" / "+goal:String.valueOf(s.total);YearStoryActivity.reward(a,label,cardValue);}).show());card.addView(share);TextView edit=a.text("Weekly goal · tap the ring to edit",11,MainActivity.GOLD);edit.setPadding(0,a.dp(8),0,0);edit.setOnClickListener(v->editGoal(a,host));card.addView(edit);
 }
 static void editGoal(MainActivity a,LinearLayout host){NumberPicker pick=new NumberPicker(a);pick.setMinValue(1);pick.setMaxValue(100);pick.setValue(goal(a.data));new AlertDialog.Builder(a).setTitle(Loc.t("Your weekly goal")).setView(pick).setNegativeButton(Loc.t("Cancel"),null).setNeutralButton(a.data.prefs().optBoolean("goalPaused")?Loc.t("Resume goal"):Loc.t("Pause goal"),(d,w)->{a.data.pref("goalPaused",!a.data.prefs().optBoolean("goalPaused"));show(a,host,false);}).setPositiveButton(Loc.t("Save"),(d,w)->{a.data.pref("weeklyGoal",pick.getValue());a.data.pref("goalPaused",false);show(a,host,false);}).show();}
 static String insight(DataStore data){LocalDate today=LocalDate.now();for(JSONObject i:DataStore.objects(data.itemsShared()))for(JSONObject v:DataStore.objects(i.optJSONArray("viewings"))){long at=DataStore.date(v.optString("watchedAt"));if(at<=0||v.optBoolean("dateUnknown")||v.optBoolean("approximate"))continue;LocalDate day=Instant.ofEpochMilli(at).atZone(ZoneId.systemDefault()).toLocalDate();if(day.getYear()<today.getYear()&&day.getMonth()==today.getMonth()&&day.getDayOfMonth()==today.getDayOfMonth())return Loc.f("On this day · %s",i.optString("title"));}String[] tips={"Every check-in makes your story richer.","Your next episode is only one tap away.","Watching anywhere counts. This history is yours."};return Loc.t(tips[Math.floorMod(today.getDayOfYear(),tips.length)]);}
 static void celebrate(android.content.Context c,DataStore data,PhoneRewards.Stats before){PhoneRewards.Stats after=stats(data);List<String> messages=new ArrayList<>();if(!data.prefs().optBoolean("goalPaused")&&PhoneRewards.goalReached(before.week,after.week,goal(data)))messages.add(Loc.t("Weekly goal reached"));for(int n:PhoneRewards.crossed(before.total,after.total))messages.add(Loc.f("%d viewings · a new milestone",n));if(after.streak>before.streak&&after.streak>1)messages.add(Loc.f("Day %d streak",after.streak));if(!messages.isEmpty())Toast.makeText(c,String.join(" · ",messages),Toast.LENGTH_LONG).show();}
}
